"""Tools for project and session navigation and management."""

from __future__ import annotations
import asyncio
import os
from pathlib import Path
from typing import Any, Optional, TYPE_CHECKING
from loguru import logger

from core.tools.base import BaseTool
from config.i18n import t

if TYPE_CHECKING:
    from agent.services.tool_context import ToolContext


class ProjectTool(BaseTool):
    """Project management tool."""
    def __init__(self, tool_context: "ToolContext"):
        self.ctx = tool_context
        self.workspace = Path(tool_context.workspace)

    @property
    def name(self) -> str:
        return "project_manager"

    @property
    def description(self) -> str:
        return (
            "项目管理工具。\n"
            "正确流程：create → switch。必须在 switch 之前完成所有配置。\n"
            "- list: 列出工作区中的所有项目。（仅 Default 工作区）\n"
            "- create: 创建新项目。传 create_on_overleaf=true 可同时在 Overleaf 上创建并自动关联（推荐）。（仅 Default 工作区）\n"
            "- import_overleaf: 从 Overleaf 导入已有项目。只需提供 overleaf_id，自动获取项目名、创建本地项目、关联并拉取文件。（仅 Default 工作区）\n"
            "- link_overleaf: 将已有的本地项目关联到 Overleaf（适用于本地先创建、后关联的场景）。本地有内容时自动 push，本地为空时从 Overleaf pull。不传 overleaf_id 时列出可选项目。（项目内也可用，自动使用当前项目名）\n"
            "- info: 查看指定项目的配置和状态（git、overleaf、main_tex 等）。（项目内也可用，自动使用当前项目名）\n"
            "- switch: 切换到指定项目，进入工作模式。（仅 Default 工作区）\n"
            "- delete: 删除本地项目（仅删除 workspace 中的目录，不影响 Overleaf 端）。需要 confirm=true 确认。（仅 Default 工作区）"
        )

    @property
    def parameters_schema(self) -> dict[str, Any]:
        return {
            "type": "object",
            "properties": {
                "action": {
                    "type": "string",
                    "enum": ["list", "create", "switch", "info", "import_overleaf", "link_overleaf", "delete"],
                    "description": "执行的动作。"
                },
                "project_name": {
                    "type": "string",
                    "description": "项目名称。create/switch/info/link_overleaf 时需要。"
                },
                "session_name": {
                    "type": "string",
                    "description": "会话名称（可选）。不传则自动生成 MMDD_NN 格式（如 0217_01）。也可传入已有 session 名称来恢复。"
                },
                "overleaf_id": {
                    "type": "string",
                    "description": "Overleaf 项目 ID（URL 中的 ID）。用于 import_overleaf 和 link_overleaf。"
                },
                "create_on_overleaf": {
                    "type": "boolean",
                    "description": "create 时是否同时在 Overleaf 上创建项目并自动关联。默认 false。"
                },
                "confirm": {
                    "type": "boolean",
                    "description": "delete 时需要传 true 以确认删除。"
                },
            },
            "required": ["action"],
        }

    def _get_project_path(self, project_name: str) -> Path:
        return self.workspace / project_name

    async def execute(self, action: str, project_name: Optional[str] = None,
                      session_name: Optional[str] = None, overleaf_id: Optional[str] = None,
                      create_on_overleaf: bool = False, confirm: bool = False,
                      **kwargs) -> str:
        # Mode check: most actions only available in Default workspace,
        # but link_overleaf and info are also usable inside a project.
        if self.ctx.project_id != "Default" and action not in ("link_overleaf", "info"):
            return t("project.not_in_default")

        if action == "list":
            return self._list()
        elif action == "create":
            if not project_name:
                return "[ERROR] 'project_name' is required."
            return await self._create(project_name, create_on_overleaf=create_on_overleaf)
        elif action == "switch":
            if not project_name:
                return "[ERROR] 'project_name' is required."
            # session_name=None lets switch_project reuse today's latest session
            return await self._switch(project_name, session_name)
        elif action == "info":
            if not project_name:
                if self.ctx.project_id != "Default":
                    project_name = self.ctx.project_id
                else:
                    return "[ERROR] 'project_name' is required."
            return self._info(project_name)
        elif action == "import_overleaf":
            if not overleaf_id:
                return "[ERROR] 'overleaf_id' is required for import_overleaf."
            return await self._import_overleaf(overleaf_id)
        elif action == "link_overleaf":
            if not project_name:
                if self.ctx.project_id != "Default":
                    project_name = self.ctx.project_id
                else:
                    return "[ERROR] 'project_name' is required."
            return await self._link_overleaf(project_name, overleaf_id)
        elif action == "delete":
            if not project_name:
                return "[ERROR] 'project_name' is required."
            return self._delete(project_name, confirm)
        else:

    else:
        return f"[ERROR] Unknown action '{action}'"

# ------------------------------------------------------------------
# list
# ------------------------------------------------------------------

def _list(self) -> str:
    if not self.workspace.exists():
        return t("project.workspace_empty")
    current = self.ctx.project_id
    projects = []
    for d in sorted(self.workspace.iterdir()):
        if not d.is_dir() or d.name in ("Default",) or d.name.startswith("."):
            continue
        config_path = d / "project.yaml"
        overleaf_tag = ""
        if config_path.exists():
            try:
                import yaml
                cfg = yaml.safe_load(config_path.read_text(encoding="utf-8")) or {}
                if cfg.get("overleaf", {}).get("project_id"):
                    overleaf_tag = " [Overleaf]"
            except Exception:
                pass
        active_tag = t("project.current_marker") if d.name == current else ""
        projects.append(f"  {d.name}{overleaf_tag}{active_tag}")

    if not projects:
        return t("project.no_projects")
    header = t("project.list_header", current=current)
    return header + "\n" + "\n".join(projects)

# ------------------------------------------------------------------
# delete
# ------------------------------------------------------------------

def _delete(self, project_name: str, confirm: bool = False) -> str:
    project_path = self._get_project_path(project_name)
    if not project_path.exists():
        return t("project.delete_not_found", project_name=project_name)
    if not confirm:
        size = sum(f.stat().st_size for f in project_path.rglob("*") if f.is_file())
        size_mb = f"{size / (1024 * 1024):.1f}"
        overleaf_note = ""
        config_path = project_path / "project.yaml"
        if config_path.exists():
            try:
                import yaml
                cfg = yaml.safe_load(config_path.read_text(encoding="utf-8")) or {}
                if cfg.get("overleaf", {}).get("project_id"):
                    overleaf_note = t("project.delete_overleaf_note")
            except Exception:
                pass
        return t("project.delete_confirm", project_name=project_name,
                 size_mb=size_mb, overleaf_note=overleaf_note)
    import shutil
    shutil.rmtree(project_path)
    logger.info(f"Deleted local project: {project_name}")
    return t("project.deleted", project_name=project_name)

# ------------------------------------------------------------------
# create
# ------------------------------------------------------------------

async def _create(self, project_name: str, create_on_overleaf: bool = False) -> str:
    from core.project import Project
    from core.automation.bootstrap import ensure_project_automation_jobs

    project_path = self._get_project_path(project_name)
    if project_path.exists():
        return f"[ERROR] Project '{project_name}' already exists. Use 'switch' to enter it."

    proj = Project(project_name, self.workspace)
    bootstrap = ensure_project_automation_jobs(proj)
    autoplan_line = await self._run_initial_autoplan(proj)

    lines = [f"✅ Project '{project_name}' created."]

    # Optionally create on Overleaf and auto-link
    if create_on_overleaf:
        try:
            from agent.tools.overleaf import OverleafTool
            ol = OverleafTool(workspace=self.workspace)
            ol_result = ol.execute(action="create_project", project_name=project_name)
            if "ERROR" in ol_result:
                lines.append(f"⚠️ Overleaf creation failed: {ol_result}")
            else:
                lines.append(f"✅ {ol_result}")
                # Extract project ID and link

