import json
import os
import re
from pathlib import Path

from openai import OpenAI

MODEL = "gpt-4o-mini"
TEMPERATURES = [0.0, 0.5, 1.0, 1.5]
N_SAMPLES = 5
PROMPT = (
    "Write a concise, original paragraph of 90--120 words about the value of reproducible "
    "experiments in machine learning. Avoid bullet points. Use plain language and do not mention "
    "that you are an AI model."
)


def tokenize(text: str):
    return re.findall(r"\w+|[^\w\s]", text.lower(), flags=re.UNICODE)


def distinct_n(texts, n):
    tokens = []
    for text in texts:
        tokens.extend(tokenize(text))
    if len(tokens) < n or len(tokens) == 0:
        return 0.0, len(tokens), 0
    ngrams = tokens if n == 1 else [tuple(tokens[i : i + n]) for i in range(len(tokens) - n + 1)]
    return len(set(ngrams)) / len(ngrams), len(tokens), len(ngrams)


def main():
    api_key = os.environ.get("OPENAI_API_KEY", "").strip()
    if not api_key or api_key.startswith("sk-proj-"):
        raise RuntimeError(
            "A valid OPENAI_API_KEY must be set before running the experiment."
        )
    client = OpenAI(api_key=api_key)
    results = {"model": MODEL, "prompt": PROMPT, "temperatures": []}
    for temp in TEMPERATURES:
        samples = []
        for _ in range(N_SAMPLES):
            resp = client.chat.completions.create(
                model=MODEL,
                messages=[{"role": "user", "content": PROMPT}],
                temperature=temp,
                n=1,
            )
            samples.append(resp.choices[0].message.content.strip())
        d1, tok_count, uni_count = distinct_n(samples, 1)
        d2, _, bi_count = distinct_n(samples, 2)
        results["temperatures"].append(
            {
                "temperature": temp,
                "n_samples": N_SAMPLES,
                "samples": samples,
                "metrics": {
                    "distinct_1": d1,
                    "distinct_2": d2,
                    "token_count": tok_count,
                    "unigram_count": uni_count,
                    "bigram_count": bi_count,
                    "tokenization": "lowercase regex tokenization: \\w+|[^\\w\\s]",
                    "scope": "concatenate the 5 outputs in a temperature group, then compute corpus-level distinct-n",
                },
            }
        )
    Path("code").mkdir(exist_ok=True)
    with open("code/results.json", "w", encoding="utf-8") as f:
        json.dump(results, f, ensure_ascii=False, indent=2)


if __name__ == "__main__":
    main()

