def _build_env() -> dict:
    """Inherit the parent environment plus the LLM credentials configured
    in settings.json, so subprocess scripts (e.g. OpenAI experiments) can
    authenticate without the user exporting keys manually."""
    import os
    env = os.environ.copy()
    try:
        from config.loader import load_config
        cfg = load_config()
        key = cfg.get_api_key()
        base = cfg.get_api_base()
        if key:
            # Only set when absent so an explicit export still wins.
            env.setdefault("OPENAI_API_KEY", key)
        if base:
            env.setdefault("OPENAI_BASE_URL", base)
    except Exception:
        # Never let credential resolution break command execution.
        pass
    return env

def execute(self, command: str, cwd: Optional[str] = None, **kwargs) -> str:
    """Execute a bash command via VFS."""

